INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4676174, 675004, 91496, '<td valign="top">Nice photo.  Filling the frame like this may be too much as it sort of freezes the motion, rather then higlighting it .  Perhaps zooming out and leaving some space on the right side or zooming in from a 3/4 angle would have added more motion or life.</td>', 'Nice photo.  Filling the frame like this may be too much as it sort of freezes the motion, rather then higlighting it .  Perhaps zooming out and leaving some space on the right side or zooming in from a 3/4 angle would have added more motion or life.', '2008-05-02 23:53:44.000000', NULL, 1),
(4676175, 675004, 83313, '<td valign="top">A nice action catch, but it seems a snapshot. A good snapshot, however.</td>', 'A nice action catch, but it seems a snapshot. A good snapshot, however.', '2008-05-02 23:54:16.000000', NULL, 1),
(4676177, 674536, 83313, '<td valign="top">A decent portrait, except for the background and the harsh shadow from the flash.</td>', 'A decent portrait, except for the background and the harsh shadow from the flash.', '2008-05-02 23:55:25.000000', NULL, 1),
(4676178, 667757, 91496, '<td valign="top">Nice photo.  Took me a while to find the itch reference in the texture and shading of the hind of the animal.  May not have been the best choice for a pose.</td>', 'Nice photo.  Took me a while to find the itch reference in the texture and shading of the hind of the animal.  May not have been the best choice for a pose.', '2008-05-02 23:55:29.000000', NULL, 1),
(4676180, 672802, 91496, '<td valign="top">Nice photo.  Might be cut up into too many zones (5-6 depending on how you count them).  Cropping the top third as a landscape would have looked pretty cool as well.</td>', 'Nice photo.  Might be cut up into too many zones (5-6 depending on how you count them).  Cropping the top third as a landscape would have looked pretty cool as well.', '2008-05-02 23:57:20.000000', NULL, 1),
(4676181, 675072, 83313, '<td valign="top">This is very interesting, but I think you went a little too far on the processing. Or maybe, not far enough. The shack appears a bit oversharpened and looks out of place.</td>', 'This is very interesting, but I think you went a little too far on the processing. Or maybe, not far enough. The shack appears a bit oversharpened and looks out of place.', '2008-05-02 23:58:10.000000', NULL, 1),
(4676182, 674996, 91496, '<td valign="top">Confusing tilt or non-tilt whichever it is.  Nice textures and clouds.</td>', 'Confusing tilt or non-tilt whichever it is.  Nice textures and clouds.', '2008-05-02 23:58:30.000000', NULL, 1),
