INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4681930, 674718, 83313, '<td valign="top">Nice view, though I may not have centered it. Personal preference is all that is.</td>', 'Nice view, though I may not have centered it. Personal preference is all that is.', '2008-05-05 14:16:05.000000', NULL, 1),
(4681935, 674754, 83313, '<td valign="top">Interesting, but the midday sun causes the usual problems withe blown highlights and shadows.</td>', 'Interesting, but the midday sun causes the usual problems withe blown highlights and shadows.', '2008-05-05 14:17:47.000000', NULL, 1),
(4681941, 674714, 83313, '<td valign="top">Not quite enough depth of field here, Could use just a little bit more of the subject in focus. It''s admittedly tough at such a close range and an angle. Perhaps pulling back just a bit could help.</td>', 'Not quite enough depth of field here, Could use just a little bit more of the subject in focus. It''s admittedly tough at such a close range and an angle. Perhaps pulling back just a bit could help.', '2008-05-05 14:20:49.000000', NULL, 1),
(4681943, 674972, 65234, '<td valign="top">Great perspective!</td>', 'Great perspective!', '2008-05-05 14:22:27.000000', NULL, 1),
(4681944, 671609, 83313, '<td valign="top">Nice detail and a wonderful deep blue in the sky. Perhaps cropped a little close for me at the tip of the flag. It seems slightly cramped vertically.</td>', 'Nice detail and a wonderful deep blue in the sky. Perhaps cropped a little close for me at the tip of the flag. It seems slightly cramped vertically.', '2008-05-05 14:22:46.000000', NULL, 1),
(4681947, 672838, 83313, '<td valign="top">Hope that''s the name of the horse, and not what it''s got!</td>', 'Hope that''s the name of the horse, and not what it''s got!', '2008-05-05 14:24:11.000000', NULL, 1),
(4681950, 667169, 83313, '<td valign="top">Funny. That''s the nature of nature, I suppose.</td>', 'Funny. That''s the nature of nature, I suppose.', '2008-05-05 14:24:59.000000', NULL, 1),
(4681951, 666641, 65234, '<td valign="top">Adorable little bird!  I love all the snowflakes and the red of the bird stands out beautifully against the green of the background.</td>', 'Adorable little bird!  I love all the snowflakes and the red of the bird stands out beautifully against the green of the background.', '2008-05-05 14:25:25.000000', NULL, 1),
(4681952, 674758, 83313, '<td valign="top">Wonderful details on this bird. B/w was a good choice, but I am curious what the color version looks like.</td>', 'Wonderful details on this bird. B/w was a good choice, but I am curious what the color version looks like.', '2008-05-05 14:26:22.000000', NULL, 1),
(4681956, 667757, 83313, '<td valign="top">A very unique view of wildlife in action!</td>', 'A very unique view of wildlife in action!', '2008-05-05 14:28:12.000000', NULL, 1),
