(4683951, 674896, 39430, '<td valign="top">Nice clean lines and sky.</td>', 'Nice clean lines and sky.', '2008-05-06 10:02:13.000000', NULL, 1),
(4683952, 672700, 674, '<td valign="top">highlights blown out</td>', 'highlights blown out', '2008-05-06 10:02:16.000000', NULL, 1),
