(4688792, 670587, 50695, '<td valign="top">campy but still a great character study</td>', 'campy but still a great character study', '2008-05-07 23:17:07.000000', NULL, 1),
(4688794, 669882, 32872, '<td valign="top">Who would have thought??  Unique capture with perfect lighting and dof...amazing detail and Bokeh.  Amazing!</td>', 'Who would have thought??  Unique capture with perfect lighting and dof...amazing detail and Bokeh.  Amazing!', '2008-05-07 23:17:20.000000', NULL, 1),
