(4688812, 673867, 50695, '<td valign="top">beautiful colors and lines. great energy.</td>', 'beautiful colors and lines. great energy.', '2008-05-07 23:19:29.000000', NULL, 1),
(4688813, 674805, 83313, '<td valign="top">Awesome view. the blue seems a touch grainy in both the sky and water.</td>', 'Awesome view. the blue seems a touch grainy in both the sky and water.', '2008-05-07 23:19:44.000000', NULL, 1),
(4688814, 675060, 50695, '<td valign="top">lovely abstract</td>', 'lovely abstract', '2008-05-07 23:20:02.000000', NULL, 1),
(4688816, 670560, 32872, '<td valign="top">Vibrant colors!  Love your composition and subject matter!</td>', 'Vibrant colors!  Love your composition and subject matter!', '2008-05-07 23:20:07.000000', NULL, 1),
(4688820, 674843, 32872, '<td valign="top">Such DOF....what a gorgeous place and day!</td>', 'Such DOF....what a gorgeous place and day!', '2008-05-07 23:20:44.000000', NULL, 1),
(4688822, 674672, 50695, '<td valign="top">intriguing composition. good natural portrait.</td>', 'intriguing composition. good natural portrait.', '2008-05-07 23:20:57.000000', NULL, 1),
(4688823, 674672, 83313, '<td valign="top">For what is clearly casual street photography, you snagged a great picture with lots of detail and character. He has that bored look from a long train ride.</td>', 'For what is clearly casual street photography, you snagged a great picture with lots of detail and character. He has that bored look from a long train ride.', '2008-05-07 23:20:57.000000', NULL, 1),
(4688824, 673607, 32872, '<td valign="top">Unique and beautiful.</td>', 'Unique and beautiful.', '2008-05-07 23:21:02.000000', NULL, 1),
(4688829, 671596, 32872, '<td valign="top">Now this is different! I like your jewel colors and crop....the tight crop makes this look very abstract..Love the bokeh.</td>', 'Now this is different! I like your jewel colors and crop....the tight crop makes this look very abstract..Love the bokeh.', '2008-05-07 23:22:04.000000', NULL, 1),
(4688830, 674951, 50695, '<td valign="top">fascinating. small subject as a keystone of a complex but geometrical composition.</td>', 'fascinating. small subject as a keystone of a complex but geometrical composition.', '2008-05-07 23:22:10.000000', NULL, 1),
(4688831, 674710, 83313, '<td valign="top">A great portrait of a lovely model.</td>', 'A great portrait of a lovely model.', '2008-05-07 23:22:21.000000', NULL, 1),
(4688833, 672792, 32872, '<td valign="top">Interesting old barn....wish I could see the whole thing.</td>', 'Interesting old barn....wish I could see the whole thing.', '2008-05-07 23:22:40.000000', NULL, 1),
(4688834, 674627, 50695, '<td valign="top">I love the texture and how the subject gets lost in it.</td>', 'I love the texture and how the subject gets lost in it.', '2008-05-07 23:23:15.000000', NULL, 1),
(4688835, 668446, 32872, '<td valign="top">Obviously they are hiding behind the tree..sorry couldn''t resist!</td>', 'Obviously they are hiding behind the tree..sorry couldn''t resist!', '2008-05-07 23:23:19.000000', NULL, 1),
(4688836, 674869, 83313, '<td valign="top">Nice view. The name sounds familiar. I may have been there as a kid. Is this is upstate N.Y.?</td>', 'Nice view. The name sounds familiar. I may have been there as a kid. Is this is upstate N.Y.?', '2008-05-07 23:23:37.000000', NULL, 1),
(4688838, 669761, 50695, '<td valign="top">great take on this subject.</td>', 'great take on this subject.', '2008-05-07 23:23:41.000000', NULL, 1),
(4688839, 674834, 32872, '<td valign="top">Neat abstract!</td>', 'Neat abstract!', '2008-05-07 23:23:41.000000', NULL, 1),
(4688844, 673020, 32872, '<td valign="top">Reminds me of a 60''s album cover for some reason!  I like the high key look.</td>', 'Reminds me of a 60''s album cover for some reason!  I like the high key look.', '2008-05-07 23:24:25.000000', NULL, 1),
(4688848, 674746, 83313, '<td valign="top">Very cool and one of the more unique sunset shots I have ever seen.</td>', 'Very cool and one of the more unique sunset shots I have ever seen.', '2008-05-07 23:25:41.000000', NULL, 1),
